<script setup>
import { ref, watch } from 'vue'
const props = defineProps({ product: {type:Object, default:null}, categories: Array })
const emit = defineEmits(['save','close'])
const form = ref({ name:'', category:'Herramientas', price:'', stock:'', minStock:5, sku:'' })
watch(() => props.product, (value)=> { form.value = value ? {...value} : {name:'',category:'Herramientas',price:'',stock:'',minStock:5,sku:''} }, {immediate:true})
function submit(){ const f=form.value; if(!f.name.trim() || !f.sku.trim() || f.price==='' || f.stock==='' || +f.price<0 || !Number.isInteger(+f.stock) || +f.stock<0 || !Number.isInteger(+f.minStock) || +f.minStock<0) return alert('Revisa los campos. Precio y cantidades no pueden ser negativos; las cantidades deben ser enteras.'); emit('save',{...f,name:f.name.trim(),sku:f.sku.trim().toUpperCase(),price:Number(f.price),stock:Number(f.stock),minStock:Number(f.minStock)}) }
</script>
<template><div class="overlay" @click.self="$emit('close')"><div class="modal"><div class="modal-head"><div><div class="eyebrow">INVENTARIO</div><h2>{{ product ? 'Editar producto' : 'Nuevo producto' }}</h2></div><button class="icon-btn" @click="$emit('close')" aria-label="Cerrar">✕</button></div><form @submit.prevent="submit" class="form-grid"><label class="field full">Nombre del producto<input v-model="form.name" required maxlength="70" placeholder="Ej. Taladro percutor 650W"/></label><label class="field">Código SKU<input v-model="form.sku" required maxlength="20" placeholder="FER-010"/></label><label class="field">Categoría<select v-model="form.category"><option v-for="cat in categories" :key="cat">{{cat}}</option></select></label><label class="field">Precio de venta (Q)<input v-model.number="form.price" type="number" min="0" step="0.01" required/></label><label class="field">Existencias<input v-model.number="form.stock" type="number" min="0" step="1" required/></label><label class="field full">Alerta de inventario a partir de<input v-model.number="form.minStock" type="number" min="0" step="1" required/></label><div class="form-actions full"><button class="btn ghost" type="button" @click="$emit('close')">Cancelar</button><button class="btn primary" type="submit">{{product?'Guardar cambios':'Agregar producto'}}</button></div></form></div></div></template>
